// ion-track-mc web page: language switch, animated proton tracks (canvas) and interactive plots (Plotly).
// All data come from data.js (window.ITMC_DATA), generated by dev_tools/export_web_data.py
// with the real ion_track_mc code. Nothing is simulated in the browser.
(function () {
  "use strict";

  const D = window.ITMC_DATA;
  const C = {
    navy: "#0b1d3a", navy2: "#16305c", amber: "#f5a524", cyan: "#1597b5", red: "#c8364b",
    green: "#2e8b57", violet: "#7b4fa0", brown: "#8c5a2b", muted: "#5b6475", border: "#d9dee6", ink: "#1d2433",
  };
  const PROC = ["ion", "exc", "cap", "los", "ela"];
  const PCOLOR = { ion: C.red, exc: C.green, cap: C.violet, los: C.brown, ela: C.cyan };
  const QCOLOR = { 1: C.navy, 0: C.amber };

  // ------------------------------------------------------------------ texts
  const TXT = {
    en: {
      title: "ion-track-mc · Proton tracks in water, collision by collision",
      proc: { ion: "ionization", exc: "excitation", cap: "capture", los: "loss", ela: "elastic" },
      play: "▶ Play", pause: "❚❚ Pause", replay: "↺ Replay",
      reset: "Back to the start", step: "One collision", end: "Show the whole track",
      hud: { col: "collision", depth: "depth z", energy: "energy", charge: "charge state", last: "last process", none: "—" },
      tip: (k, p, dE, E, q, z, x) => `#${k} · <b>${p}</b><br>ΔE = ${dE} eV · E after = ${E} keV<br>${q} · z = ${z} nm, x = ${x} nm`,
      caption: {
        t15_25: (n, r) => `The first 25 nm of a 15 keV proton track in water (${n} collisions in total, range ${r} nm). Low energy: collisions every ~0.1–0.3 nm, frequent charge exchange.`,
        t15_full: (n, r) => `The whole track of a 15 keV proton: ${n} collisions over ${r} nm, until its energy falls below 8 keV. Note how often it travels as H⁰ at these energies.`,
        t500_130: (n, r) => `The first 131 nm of a 500 keV proton (the same length as the whole 15 keV track; ${n} collisions in total over ${r} nm). Faster protons collide less often: lower LET.`,
      },
      ax: { depth: "Depth z (nm)", x: "x (nm)", E: "Projectile energy (keV)", Ep: "Proton energy (keV)", xs: "Cross section σ (nm²)",
        mfp: "Mean free path λ (nm)", frac: "Equilibrium fraction", sp: "Stopping power (keV/µm)", depthum: "Depth (µm)",
        dose: "Dose (relative)", r: "Distance from the track axis r (nm)", dr: "Dose per proton (Gy)", zum: "Depth z (µm)" },
      model: "ion-track-mc (charge equilibrium)", modelp: "ion-track-mc, H⁺ only", model0: "ion-track-mc, H⁰ only",
      pstar: "NIST PSTAR (liquid water)", vapour: "vapour", liquid: "liquid", mfp: "λ",
      path: "path", let: (n, lt, ld) => `Beam of <strong>${n} protons of 1 MeV</strong> in water, LET measured on 1 µm segments: track-averaged <strong>L̄<sub>T</sub> = ${lt} keV/µm</strong>, dose-averaged <strong>L̄<sub>D</sub> = ${ld} keV/µm</strong>. L̄<sub>D</sub> &gt; L̄<sub>T</sub> because the dense end of each track weighs more in dose.`,
      copy: "Copy", copyBib: "Copy BibTeX", copied: "Copied to the clipboard", copyFail: "Could not copy: select the text by hand",
      Eafter: "E after",
    },
    es: {
      title: "ion-track-mc · Trazas de protones en agua, colisión por colisión",
      proc: { ion: "ionización", exc: "excitación", cap: "captura", los: "pérdida", ela: "elástica" },
      play: "▶ Reproducir", pause: "❚❚ Pausa", replay: "↺ Repetir",
      reset: "Volver al principio", step: "Una colisión", end: "Mostrar la traza completa",
      hud: { col: "colisión", depth: "profundidad z", energy: "energía", charge: "estado de carga", last: "último proceso", none: "—" },
      tip: (k, p, dE, E, q, z, x) => `#${k} · <b>${p}</b><br>ΔE = ${dE} eV · E después = ${E} keV<br>${q} · z = ${z} nm, x = ${x} nm`,
      caption: {
        t15_25: (n, r) => `Los primeros 25 nm de la traza de un protón de 15 keV en agua (${n} colisiones en total, alcance ${r} nm). Baja energía: colisiones cada ~0,1–0,3 nm y cambios de carga frecuentes.`,
        t15_full: (n, r) => `La traza completa de un protón de 15 keV: ${n} colisiones en ${r} nm, hasta que su energía cae por debajo de 8 keV. A estas energías viaja buena parte del camino como H⁰.`,
        t500_130: (n, r) => `Los primeros 131 nm de un protón de 500 keV (la misma longitud que toda la traza de 15 keV; ${n} colisiones en total en ${r} nm). Los protones más rápidos chocan con menos frecuencia: menor TEL.`,
      },
      ax: { depth: "Profundidad z (nm)", x: "x (nm)", E: "Energía del proyectil (keV)", Ep: "Energía del protón (keV)", xs: "Sección eficaz σ (nm²)",
        mfp: "Camino libre medio λ (nm)", frac: "Fracción de equilibrio", sp: "Poder de frenado (keV/µm)", depthum: "Profundidad (µm)",
        dose: "Dosis (relativa)", r: "Distancia al eje de la traza r (nm)", dr: "Dosis por protón (Gy)", zum: "Profundidad z (µm)" },
      model: "ion-track-mc (equilibrio de carga)", modelp: "ion-track-mc, solo H⁺", model0: "ion-track-mc, solo H⁰",
      pstar: "NIST PSTAR (agua líquida)", vapour: "vapor", liquid: "líquido", mfp: "λ",
      path: "camino", let: (n, lt, ld) => `Haz de <strong>${n} protones de 1 MeV</strong> en agua, TEL medida en segmentos de 1 µm: promediada en traza <strong>L̄<sub>T</sub> = ${lt} keV/µm</strong>, promediada en dosis <strong>L̄<sub>D</sub> = ${ld} keV/µm</strong>. L̄<sub>D</sub> &gt; L̄<sub>T</sub> porque el final denso de cada traza pesa más en la dosis.`,
      copy: "Copiar", copyBib: "Copiar BibTeX", copied: "Copiado al portapapeles", copyFail: "No se pudo copiar: seleccione el texto manualmente",
      Eafter: "E después",
    },
  };
  let LANG = "es";
  const T = () => TXT[LANG];
  const num = (v, d) => { const s = (+v).toFixed(d); return LANG === "es" ? s.replace(".", ",") : s; };
  const int = (v) => Math.round(v).toLocaleString(LANG === "es" ? "es-AR" : "en-US");

  // ------------------------------------------------------------------ language
  function detectLang() {
    const q = new URLSearchParams(location.search).get("lang");
    if (q === "en" || q === "es") return q;
    try { const s = localStorage.getItem("itmc-lang"); if (s === "en" || s === "es") return s; } catch (e) { /* storage blocked */ }
    return "es";
  }

  function setLang(l) {
    LANG = l;
    document.documentElement.lang = l;
    document.title = T().title;
    try { localStorage.setItem("itmc-lang", l); } catch (e) { /* storage blocked */ }
    document.querySelectorAll(".lang-switch button").forEach((b) => b.setAttribute("aria-pressed", String(b.dataset.lang === l)));
    document.querySelectorAll("[data-en][data-es]").forEach((el) => { el.textContent = el.dataset[l]; });
    document.querySelectorAll("[data-href-en]").forEach((el) => { el.href = el.dataset["href" + (l === "es" ? "Es" : "En")]; });
    document.querySelectorAll(".copy").forEach((b) => { b.textContent = b.dataset.bib ? T().copyBib : T().copy; });
    Track.relabel();
    renderPlots();
  }

  // ------------------------------------------------------------------ helpers
  function niceTicks(lo, hi, n) {
    const span = hi - lo, raw = span / Math.max(n, 1), mag = Math.pow(10, Math.floor(Math.log10(raw)));
    const step = [1, 2, 2.5, 5, 10].map((m) => m * mag).find((s) => span / s <= n) || 10 * mag;
    const out = [];
    for (let v = Math.ceil(lo / step) * step; v <= hi + 1e-9 * span; v += step) out.push(+v.toFixed(10));
    return { ticks: out, step };
  }
  function tickLabel(v, step) {
    const d = Math.max(0, -Math.floor(Math.log10(step) + 1e-9));
    return num(v, Math.min(d + (step % 1 && (step * Math.pow(10, d)) % 1 ? 1 : 0), 4));
  }
  function toast(msg) {
    const t = document.getElementById("toast");
    t.textContent = msg; t.classList.add("show");
    clearTimeout(toast.h); toast.h = setTimeout(() => t.classList.remove("show"), 2000);
  }

  // ------------------------------------------------------------------ animated track (canvas)
  const Track = (function () {
    const cv = document.getElementById("track-canvas"), ctx = cv.getContext("2d");
    const tip = document.getElementById("track-tip");
    const hud = document.getElementById("track-hud"), tally = document.getElementById("track-tally");
    const sel = document.getElementById("track-preset"), btnPlay = document.getElementById("track-play");
    const speed = document.getElementById("track-speed");
    const M = { l: 58, r: 18, t: 16, b: 44 };
    const hidden = new Set();
    let tr, N, k = 0, playing = false, acc = 0, last = 0, W = 0, H = 0, X0, X1, Y0, Y1, px = [], py = [], hover = -1;

    function load(key) {
      tr = D.tracks[key]; N = tr.z.length; k = 0; acc = 0; hover = -1;
      X0 = 0; X1 = key === "t15_full" ? Math.ceil(tr.range_nm / 5) * 5 : (key === "t15_25" ? 25 : 131);
      let lo = 0, hi = 0;
      for (const v of tr.x) { if (v < lo) lo = v; if (v > hi) hi = v; }
      const pad = Math.max(0.15 * (hi - lo), 0.1); Y0 = lo - pad; Y1 = hi + pad;
      if (Y1 - Y0 < 0.6) { const m = (Y0 + Y1) / 2; Y0 = m - 0.3; Y1 = m + 0.3; }
      resize(); relabel();
    }
    function resize() {
      const dpr = window.devicePixelRatio || 1, r = cv.getBoundingClientRect();
      W = r.width; H = r.height; cv.width = Math.round(W * dpr); cv.height = Math.round(H * dpr);
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      px = tr.z.map(sx); py = tr.x.map(sy);
      draw();
    }
    const sx = (z) => M.l + (z - X0) / (X1 - X0) * (W - M.l - M.r);
    const sy = (x) => H - M.b - (x - Y0) / (Y1 - Y0) * (H - M.t - M.b);

    function axes() {
      ctx.font = "12px system-ui, sans-serif"; ctx.textBaseline = "middle";
      const xt = niceTicks(X0, X1, Math.max(3, Math.floor((W - M.l - M.r) / 70)));
      const yt = niceTicks(Y0, Y1, Math.max(3, Math.floor((H - M.t - M.b) / 45)));
      ctx.strokeStyle = "#eef1f6"; ctx.lineWidth = 1;
      for (const v of xt.ticks) { const x = Math.round(sx(v)) + 0.5; ctx.beginPath(); ctx.moveTo(x, M.t); ctx.lineTo(x, H - M.b); ctx.stroke(); }
      for (const v of yt.ticks) { const y = Math.round(sy(v)) + 0.5; ctx.beginPath(); ctx.moveTo(M.l, y); ctx.lineTo(W - M.r, y); ctx.stroke(); }
      ctx.strokeStyle = C.muted; ctx.beginPath(); ctx.moveTo(M.l, M.t); ctx.lineTo(M.l, H - M.b); ctx.lineTo(W - M.r, H - M.b); ctx.stroke();
      ctx.fillStyle = C.muted; ctx.textAlign = "center";
      for (const v of xt.ticks) ctx.fillText(tickLabel(v, xt.step), sx(v), H - M.b + 14);
      ctx.textAlign = "right";
      for (const v of yt.ticks) ctx.fillText(tickLabel(v, yt.step), M.l - 7, sy(v));
      ctx.textAlign = "center"; ctx.fillStyle = C.ink; ctx.font = "13px system-ui, sans-serif";
      ctx.fillText(T().ax.depth, M.l + (W - M.l - M.r) / 2, H - 12);
      ctx.save(); ctx.translate(15, M.t + (H - M.t - M.b) / 2); ctx.rotate(-Math.PI / 2); ctx.fillText(T().ax.x, 0, 0); ctx.restore();
    }

    function draw() {
      if (!W) return;
      ctx.clearRect(0, 0, W, H);
      axes();
      ctx.save(); ctx.beginPath(); ctx.rect(M.l, M.t - 6, W - M.l - M.r + 6, H - M.t - M.b + 12); ctx.clip();
      // path: segment i ends at collision i, coloured by the charge state on it
      ctx.lineWidth = 2; ctx.lineCap = "round";
      let x0 = sx(0), y0 = sy(0);
      for (let i = 0; i < k; i++) {
        ctx.strokeStyle = QCOLOR[tr.q[i]]; ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(px[i], py[i]); ctx.stroke();
        x0 = px[i]; y0 = py[i];
      }
      const rad = N > 300 ? 3.4 : 4.6;
      for (let i = 0; i < k; i++) {
        if (hidden.has(tr.c[i])) continue;
        ctx.fillStyle = PCOLOR[tr.c[i]]; ctx.strokeStyle = "#fff"; ctx.lineWidth = 0.8;
        ctx.beginPath(); ctx.arc(px[i], py[i], i === hover ? rad + 2.5 : rad, 0, 2 * Math.PI); ctx.fill(); ctx.stroke();
      }
      // projectile head
      if (k > 0 && k < N) {
        const g = ctx.createRadialGradient(px[k - 1], py[k - 1], 0, px[k - 1], py[k - 1], 14);
        g.addColorStop(0, QCOLOR[tr.q[Math.min(k, N - 1)]] + "aa"); g.addColorStop(1, "#ffffff00");
        ctx.fillStyle = g; ctx.beginPath(); ctx.arc(px[k - 1], py[k - 1], 14, 0, 2 * Math.PI); ctx.fill();
      }
      ctx.restore();
      // legend (charge state)
      ctx.font = "12px system-ui, sans-serif"; ctx.textAlign = "left"; ctx.textBaseline = "middle";
      let lx = M.l + 10;
      for (const [q, lab] of [[1, "H⁺"], [0, "H⁰"]]) {
        ctx.strokeStyle = QCOLOR[q]; ctx.lineWidth = 3; ctx.beginPath(); ctx.moveTo(lx, M.t + 6); ctx.lineTo(lx + 18, M.t + 6); ctx.stroke();
        ctx.fillStyle = C.ink; ctx.fillText(lab, lx + 23, M.t + 6); lx += 56;
      }
      updateReadout();
    }

    function updateReadout() {
      const t = T(), i = k - 1;
      const E = i >= 0 ? tr.E[i] : tr.E0_keV, z = i >= 0 ? tr.z[i] : 0;
      const q = k === 0 ? 1 : (k < N ? tr.q[k] : (tr.c[i] === "cap" ? 0 : tr.c[i] === "los" ? 1 : tr.q[i]));
      hud.innerHTML =
        `<div><span>${t.hud.col}</span><b>${int(k)} / ${int(N)}</b></div>` +
        `<div><span>${t.hud.depth}</span><b>${num(z, 2)} nm</b></div>` +
        `<div><span>${t.hud.energy}</span><b>${num(E, 3)} keV</b></div>` +
        `<div><span>${t.hud.charge}</span><b style="color:${q ? C.navy : "#c98a10"}">${q ? "H⁺" : "H⁰"}</b></div>` +
        `<div><span>${t.hud.last}</span><b style="color:${i >= 0 ? PCOLOR[tr.c[i]] : C.muted}">${i >= 0 ? t.proc[tr.c[i]] : t.hud.none}</b></div>`;
      const cnt = { ion: 0, exc: 0, cap: 0, los: 0, ela: 0 };
      for (let j = 0; j < k; j++) cnt[tr.c[j]]++;
      PROC.forEach((p) => {
        const el = tally.querySelector(`[data-p="${p}"]`);
        el.querySelector(".n").textContent = int(cnt[p]);
        el.querySelector("i").style.width = (k ? 100 * cnt[p] / k : 0) + "%";
      });
      btnPlay.textContent = playing ? t.pause : (k >= N ? t.replay : t.play);
    }

    function buildTally() {
      tally.innerHTML = PROC.map((p) => `<button type="button" class="chip" data-p="${p}" aria-pressed="true">
        <span class="dot" style="background:${PCOLOR[p]}"></span><span class="lab" data-en="${TXT.en.proc[p]}" data-es="${TXT.es.proc[p]}">${TXT.en.proc[p]}</span>
        <span class="bar"><i style="background:${PCOLOR[p]}"></i></span><span class="n">0</span></button>`).join("");
      tally.querySelectorAll(".chip").forEach((b) => b.addEventListener("click", () => {
        const p = b.dataset.p;
        if (hidden.has(p)) hidden.delete(p); else hidden.add(p);
        b.classList.toggle("off", hidden.has(p)); b.setAttribute("aria-pressed", String(!hidden.has(p)));
        draw();
      }));
    }

    const rate = () => 3 * Math.pow(10, speed.value / 38);   // collisions per second
    function tick(ts) {
      if (!playing) return;
      const dt = Math.min((ts - last) / 1000, 0.1); last = ts;
      acc += dt * rate();
      const n = Math.floor(acc);
      if (n > 0) { acc -= n; k = Math.min(N, k + n); draw(); }
      if (k >= N) { playing = false; updateReadout(); return; }
      requestAnimationFrame(tick);
    }
    function play() {
      if (k >= N) k = 0;
      playing = true; last = performance.now(); acc = 0; updateReadout(); requestAnimationFrame(tick);
    }
    function pause() { playing = false; updateReadout(); }

    function relabel() {
      const t = T();
      [...sel.options].forEach((o) => { o.textContent = o.dataset[LANG]; });
      document.getElementById("track-reset").title = t.reset;
      document.getElementById("track-step").title = t.step;
      document.getElementById("track-end").title = t.end;
      document.getElementById("track-caption").textContent = t.caption[sel.value](int(tr.n_total), int(tr.range_nm));
      draw();
    }

    function onMove(ev) {
      const r = cv.getBoundingClientRect(), mx = ev.clientX - r.left, my = ev.clientY - r.top;
      let best = -1, bd = 144;
      for (let i = 0; i < k; i++) {
        if (hidden.has(tr.c[i])) continue;
        const d = (px[i] - mx) ** 2 + (py[i] - my) ** 2;
        if (d < bd) { bd = d; best = i; }
      }
      if (best !== hover) { hover = best; draw(); }
      if (best < 0) { tip.style.opacity = 0; return; }
      const t = T(), q = tr.q[best];
      tip.innerHTML = t.tip(best + 1, t.proc[tr.c[best]], num(tr.dE[best], 1), num(tr.E[best], 3),
        q ? "H⁺" : "H⁰", num(tr.z[best], 2), num(tr.x[best], 3));
      const tw = tip.offsetWidth;
      tip.style.left = Math.min(Math.max(px[best] - tw / 2, 4), W - tw - 4) + "px";
      tip.style.top = Math.max(py[best] - tip.offsetHeight - 12, 2) + "px";
      tip.style.opacity = 1;
    }

    function init() {
      buildTally();
      load(sel.value);
      sel.addEventListener("change", () => { pause(); load(sel.value); play(); });
      btnPlay.addEventListener("click", () => (playing ? pause() : play()));
      document.getElementById("track-step").addEventListener("click", () => { pause(); k = Math.min(N, k + 1); draw(); });
      document.getElementById("track-reset").addEventListener("click", () => { pause(); k = 0; draw(); });
      document.getElementById("track-end").addEventListener("click", () => { pause(); k = N; draw(); });
      cv.addEventListener("mousemove", onMove);
      cv.addEventListener("mouseleave", () => { tip.style.opacity = 0; hover = -1; draw(); });
      let rt; window.addEventListener("resize", () => { clearTimeout(rt); rt = setTimeout(resize, 120); });
      const reduce = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
      if (reduce || !("IntersectionObserver" in window)) { k = N; draw(); return; }
      const io = new IntersectionObserver((es) => { if (es.some((e) => e.isIntersecting)) { io.disconnect(); play(); } }, { threshold: 0.4 });
      io.observe(cv);
    }
    return { init, relabel: () => tr && relabel() };
  })();

  // ------------------------------------------------------------------ plots
  const CONFIG = { responsive: true, displaylogo: false, modeBarButtonsToRemove: ["lasso2d", "select2d", "autoScale2d"],
    toImageButtonOptions: { format: "png", scale: 2, filename: "ion-track-mc" } };
  function base(extra) {
    const ax = { showline: true, linecolor: C.muted, ticks: "outside", tickcolor: C.muted, gridcolor: "#eef1f6", zeroline: false,
      exponentformat: "power", title: { font: { size: 13 } } };
    const logAx = (o) => (o && o.type === "log" ? Object.assign({ dtick: 1 }, o) : o);
    const L = {
      font: { family: '"Source Sans 3", system-ui, -apple-system, "Segoe UI", Roboto, sans-serif', size: 13, color: C.ink },
      margin: { l: 66, r: 14, t: 12, b: 52 }, paper_bgcolor: "#fff", plot_bgcolor: "#fff",
      separators: LANG === "es" ? ",." : ".,", hovermode: "closest",
      hoverlabel: { bgcolor: C.navy, bordercolor: C.navy, font: { color: "#fff", size: 12 } },
      legend: { bgcolor: "rgba(255,255,255,.9)", font: { size: 12 } },
    };
    L.xaxis = Object.assign({}, ax, logAx(extra.xaxis)); L.yaxis = Object.assign({}, ax, logAx(extra.yaxis));
    delete extra.xaxis; delete extra.yaxis;
    return Object.assign(L, extra);
  }
  const draw = (id, traces, layout) => Plotly.react(id, traces, layout, CONFIG);

  let xsQ = "1", xsMode = "xs", spLog = true, t1Zoom = "all";

  function plotXS() {
    const t = T(), d = D.xs[xsQ];
    let traces;
    if (xsMode === "xs") {
      traces = PROC.filter((p) => d[p]).map((p) => ({ x: d.E_keV, y: d[p], name: t.proc[p], mode: "lines", line: { color: PCOLOR[p], width: 2.6 },
        hovertemplate: `${t.proc[p]}<br>E = %{x:.3g} keV<br>σ = %{y:.3g} nm²<extra></extra>` }));
    } else {
      traces = [{ x: d.E_keV, y: d.mfp_nm, name: "λ", mode: "lines", line: { color: xsQ === "1" ? C.navy : C.amber, width: 2.8 },
        hovertemplate: "E = %{x:.3g} keV<br>λ = %{y:.3g} nm<extra></extra>", showlegend: false }];
    }
    draw("plot-xs", traces, base({
      xaxis: { type: "log", title: { text: t.ax.E } },
      yaxis: { type: "log", title: { text: xsMode === "xs" ? t.ax.xs : t.ax.mfp }, range: xsMode === "xs" ? [-6, 0] : undefined },
      legend: { x: 1, xanchor: "right", y: 0, yanchor: "bottom", bgcolor: "rgba(255,255,255,.9)" },
    }));
  }

  function plotCharge() {
    const t = T(), d = D.charge;
    draw("plot-charge", [
      { x: d.E_keV, y: d.fp, name: "H⁺", mode: "lines", line: { color: C.navy, width: 3 }, hovertemplate: "H⁺ · E = %{x:.3g} keV<br>f = %{y:.3f}<extra></extra>" },
      { x: d.E_keV, y: d.f0, name: "H⁰", mode: "lines", line: { color: C.amber, width: 3 }, hovertemplate: "H⁰ · E = %{x:.3g} keV<br>f = %{y:.3f}<extra></extra>" },
    ], base({ xaxis: { type: "log", title: { text: t.ax.E } }, yaxis: { range: [0, 1.02], title: { text: t.ax.frac } },
      legend: { x: 1, xanchor: "right", y: 0.5, yanchor: "middle" } }));
  }

  function plotSP() {
    const t = T(), d = D.sp, showQ = document.getElementById("sp-charge").checked;
    const sym = ["triangle-down", "triangle-up", "diamond", "square", "circle"];
    const col = [C.navy2, C.cyan, C.violet, C.green, C.brown];
    const traces = d.exp.map((e, i) => ({
      x: e.E_keV, y: e.S, error_y: { type: "data", array: e.err, thickness: 1, width: 0, color: col[i] },
      name: `${e.name} (${t[e.phase]})`, mode: "markers", marker: { symbol: sym[i], size: 7, color: col[i], opacity: 0.85 },
      hovertemplate: `<b>${e.name}</b> (${t[e.phase]})<br>doi:${e.doi}<br>E = %{x:.4g} keV<br>S = %{y:.3g} ± %{error_y.array:.2g} keV/µm<extra></extra>`,
    }));
    traces.push({ x: d.pstar.E_keV, y: d.pstar.S, name: t.pstar, mode: "lines", line: { color: C.ink, dash: "dash", width: 1.8 },
      hovertemplate: `PSTAR<br>E = %{x:.4g} keV<br>S = %{y:.3g} keV/µm<extra></extra>` });
    if (showQ) {
      traces.push({ x: d.model.E_keV, y: d.model.Sp, name: t.modelp, mode: "lines", line: { color: C.navy, dash: "dot", width: 2.2 },
        hovertemplate: `${t.modelp}<br>E = %{x:.3g} keV<br>S = %{y:.3g} keV/µm<extra></extra>` });
      traces.push({ x: d.model.E_keV, y: d.model.S0, name: t.model0, mode: "lines", line: { color: C.amber, dash: "dot", width: 2.2 },
        hovertemplate: `${t.model0}<br>E = %{x:.3g} keV<br>S = %{y:.3g} keV/µm<extra></extra>` });
    }
    traces.push({ x: d.model.E_keV, y: d.model.S, name: t.model, mode: "lines", line: { color: C.red, width: 3.4 },
      hovertemplate: `ion-track-mc<br>E = %{x:.3g} keV<br>S = %{y:.3g} keV/µm<extra></extra>` });
    draw("plot-sp", traces, base({
      xaxis: spLog ? { type: "log", range: [0, 5], title: { text: t.ax.Ep } } : { type: "linear", range: [0, 1000], title: { text: t.ax.Ep } },
      yaxis: { range: [0, showQ ? 160 : 115], title: { text: t.ax.sp } },
      legend: { x: 0.995, xanchor: "right", y: 0.995, yanchor: "top", font: { size: 11.5 } },
    }));
  }

  function plotDose() {
    const t = T(), b = D.beam;
    draw("plot-bragg", [{ x: b.z_um, y: b.D, mode: "lines", line: { shape: "hvh", color: C.navy, width: 2.6 }, fill: "tozeroy",
      fillcolor: "rgba(21,151,181,.12)", hovertemplate: `z = %{x:.2f} µm<br>D/D<sub>max</sub> = %{y:.3f}<extra></extra>`, showlegend: false }],
    base({ xaxis: { range: [0, 26], title: { text: t.ax.depthum } }, yaxis: { range: [0, 1.08], title: { text: t.ax.dose } } }));
    draw("plot-radial", [{ x: b.r_nm, y: b.Dr, mode: "lines+markers", line: { color: C.cyan, width: 2.4 }, marker: { size: 7 },
      hovertemplate: `r = %{x:.3g} nm<br>D = %{y:.3g} Gy<extra></extra>`, showlegend: false }],
    base({ xaxis: { type: "log", title: { text: t.ax.r } }, yaxis: { type: "log", title: { text: t.ax.dr } } }));
    document.getElementById("let-key").innerHTML = t.let(b.n, num(b.LET_T, 1), num(b.LET_D, 1));
    document.getElementById("beam-n1").textContent = b.n; document.getElementById("beam-n2").textContent = b.n;
  }

  function plotTrack1() {
    const t = T(), d = D.track1MeV, R = d.range_nm / 1000;
    const zum = d.z.map((z) => z / 1000);
    const traces = [{ x: zum, y: d.x, mode: "lines", type: "scattergl", line: { color: "#9aa6bb", width: 1 }, name: t.path, hoverinfo: "skip" }];
    PROC.forEach((p) => {
      const xs = [], ys = [], es = [];
      for (let i = 0; i < d.c.length; i++) if (d.c[i] === p) { xs.push(zum[i]); ys.push(d.x[i]); es.push(d.E[i]); }
      traces.push({ x: xs, y: ys, customdata: es, mode: "markers", type: "scattergl", name: t.proc[p],
        marker: { color: PCOLOR[p], size: 5, line: { width: 0 } },
        hovertemplate: `${t.proc[p]}<br>z = %{x:.4f} µm · x = %{y:.2f} nm<br>${t.Eafter} = %{customdata:.1f} keV<extra></extra>` });
    });
    let xr = [0, Math.ceil(R)];
    if (t1Zoom === "start") xr = [0, 0.1];
    if (t1Zoom === "end") xr = [R - 1, R + 0.02];
    let lo = Infinity, hi = -Infinity;
    for (let i = 0; i < zum.length; i++) if (zum[i] >= xr[0] && zum[i] <= xr[1]) { lo = Math.min(lo, d.x[i]); hi = Math.max(hi, d.x[i]); }
    const pad = Math.max(0.1 * (hi - lo), 0.2);
    draw("plot-track1", traces, base({
      xaxis: { range: xr, title: { text: t.ax.zum } }, yaxis: { range: [lo - pad, hi + pad], title: { text: t.ax.x } },
      legend: { orientation: "h", x: 0, y: 1.02, yanchor: "bottom" }, margin: { l: 66, r: 14, t: 34, b: 52 },
    }));
    document.getElementById("t1-n-en").textContent = int(d.n_total);
    document.getElementById("t1-n-es").textContent = int(d.n_total);
  }

  function fillTable() {
    const tb = document.querySelector("#sp-table tbody");
    tb.innerHTML = D.sp.table.map(([e, m, p, r]) =>
      `<tr><td class="num">${int(e)}</td><td class="num">${num(m, 1)}</td><td class="num">${num(p, 1)}</td><td class="num">${num(r, 2)}</td></tr>`).join("");
  }

  let plotted = false;
  function renderPlots() {
    if (!window.Plotly) return;
    plotXS(); plotCharge(); plotSP(); plotDose(); plotTrack1(); fillTable();
    plotted = true;
  }

  function segment(id, attr, set) {
    const g = document.getElementById(id);
    g.addEventListener("click", (ev) => {
      const b = ev.target.closest("button"); if (!b) return;
      g.querySelectorAll("button").forEach((x) => x.setAttribute("aria-pressed", String(x === b)));
      set(b.dataset[attr]);
    });
  }

  // ------------------------------------------------------------------ copy buttons, nav
  function initCopy() {
    document.querySelectorAll(".copy").forEach((b) => b.addEventListener("click", async () => {
      const text = document.getElementById(b.dataset.copy).innerText.trim();
      try { await navigator.clipboard.writeText(text); toast(T().copied); }
      catch (e) {
        const ta = document.createElement("textarea"); ta.value = text; document.body.appendChild(ta); ta.select();
        try { document.execCommand("copy"); toast(T().copied); } catch (e2) { toast(T().copyFail); }
        ta.remove();
      }
    }));
  }
  function initNav() {
    if (!("IntersectionObserver" in window)) return;
    const links = new Map([...document.querySelectorAll(".topbar nav a")].map((a) => [a.getAttribute("href").slice(1), a]));
    const io = new IntersectionObserver((es) => es.forEach((e) => {
      if (e.isIntersecting) { links.forEach((a) => a.classList.remove("active")); const a = links.get(e.target.id); if (a) a.classList.add("active"); }
    }), { rootMargin: "-45% 0px -50% 0px" });
    links.forEach((_, id) => { const s = document.getElementById(id); if (s) io.observe(s); });
  }

  // ------------------------------------------------------------------ start
  document.querySelectorAll(".lang-switch button").forEach((b) => b.addEventListener("click", () => setLang(b.dataset.lang)));
  segment("xs-q", "q", (v) => { xsQ = v; plotXS(); });
  segment("xs-mode", "m", (v) => { xsMode = v; plotXS(); });
  segment("sp-scale", "s", (v) => { spLog = v === "log"; plotSP(); });
  segment("t1-zoom", "z", (v) => { t1Zoom = v; plotTrack1(); });
  document.getElementById("sp-charge").addEventListener("change", plotSP);
  initCopy(); initNav();
  LANG = detectLang();
  Track.init();
  setLang(LANG);
})();
